const q = (id, chapter, page, prompt, correctIndex, options) => ({
  id,
  chapter,
  page,
  prompt,
  options: options.map(([text, explanation], index) => ({
    id: String.fromCharCode(97 + index),
    text,
    explanation,
  })),
  correctId: String.fromCharCode(97 + correctIndex),
});

const caseQ = (...args) => ({ ...q(...args), caseStudy: true });

